import numpy as np
# invalid input: a singular edge matrix must raise ValueError
def _catches_value_error(fn):
    try:
        fn()
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])
assert np.allclose(_catches_value_error(lambda: lattice_census(1, np.zeros((3, 3)))), target)

